/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

/*--------------------------------------------------------------------------*/

void evt_notify (UInt8 event)
{
	Evt_Entry* evt_entry ;

    evt_init();

    evt_entry = evt_search( event );
    
    if( evt_entry )
    {
        if( evt_entry->set_func )
        {
            evt_entry->set_func( evt_entry->set_arg ) ;
        }
            
                
        if( !evt_entry->guard_func || ( evt_entry->guard_func() == evt_entry->guard_ret ) )
        {            
            cmd_q_rs_insert( (Cmd)evt_entry->cmd_msg , EVENT_Q_TIMEOUT , NULL ) ;
            	
            EVT_TRACE("\n\r[EVT NOTIFY VALID %02X]\n\r" , evt_entry->evt ) ;
        }
        else
        {
            EVT_TRACE("\n\r[EVT NOTIFY BLOCKED %02X]\n\r" , evt_entry->evt ) ;            
        }
    }
    else
    {        
    	EVT_TRACE("\n\r[EVT NOTIFY INVALID: 0x%02X IS NOT VALID]\n\r", evt_entry->evt) ;
    }
}

